module ClockDividerN (
	clk_out,
	clk_in
);
	parameter DIV = 1;
	output reg clk_out;
	input clk_in;
	localparam CWIDTH = $clog2(DIV);
	localparam LOW_CYCLES = DIV / 2;
	localparam HIGH_TRANSITION = LOW_CYCLES - 1;
	localparam LOW_TRANSITION = DIV - 1;
	generate
		if (DIV == 1) begin : genblk1
			always @(clk_in) clk_out = clk_in;
		end
		else begin : genblk1
			reg [CWIDTH - 1:0] count = HIGH_TRANSITION[CWIDTH - 1:0];
			always @(posedge clk_in)
				if (count == LOW_TRANSITION[CWIDTH - 1:0]) begin
					clk_out = 1'b0;
					count <= 1'sb0;
				end
				else begin
					if (count == HIGH_TRANSITION[CWIDTH - 1:0])
						clk_out = 1'b1;
					count <= count + 1'b1;
				end
		end
	endgenerate
endmodule
module EICG_wrapper (
	out,
	en,
	test_en,
	in
);
	output out;
	input en;
	input test_en;
	input in;
	reg en_latched;
	always @(*)
		if (!in)
			en_latched = en || test_en;
	assign out = en_latched && in;
endmodule
module GenericAnalogIOCell (
	pad,
	core
);
	inout pad;
	inout core;
	assign core = 1'bz;
	assign pad = core;
endmodule
module GenericDigitalGPIOCell (
	pad,
	i,
	ie,
	o,
	oe
);
	inout pad;
	output i;
	input ie;
	input o;
	input oe;
	assign pad = (oe ? o : 1'bz);
	assign i = (ie ? pad : 1'b0);
endmodule
module GenericDigitalInIOCell (
	pad,
	i,
	ie
);
	input pad;
	output i;
	input ie;
	assign i = (ie ? pad : 1'b0);
endmodule
module GenericDigitalOutIOCell (
	pad,
	o,
	oe
);
	output pad;
	input o;
	input oe;
	assign pad = (oe ? o : 1'bz);
endmodule
module plusarg_reader (out);
	parameter FORMAT = "borked=%d";
	parameter WIDTH = 1;
	parameter [WIDTH - 1:0] DEFAULT = 0;
	output [WIDTH - 1:0] out;
	reg [WIDTH - 1:0] myplus;
	assign out = myplus;
	initial if (!$value$plusargs(FORMAT, myplus))
		myplus = DEFAULT;
endmodule
