module SRAM1RW256x128_1bit (
	CE_i,
	WEB_i,
	A_i,
	OEB_i,
	CSB_i,
	I_i,
	O_i
);
	input CSB_i;
	input OEB_i;
	input CE_i;
	input WEB_i;
	input [7:0] A_i;
	input [0:0] I_i;
	output reg [0:0] O_i;
	reg [0:0] memory [255:0];
	reg [0:0] data_out;
	wire RE;
	wire WE;
	and u1 (RE, ~CSB_i, WEB_i);
	and u2 (WE, ~CSB_i, ~WEB_i);
	always @(posedge CE_i)
		if (RE)
			data_out = memory[A_i];
	always @(posedge CE_i)
		if (WE)
			memory[A_i] = I_i;
	always @(posedge CE_i)
		if (!OEB_i)
			O_i = data_out;
		else
			O_i = 1'bz;
endmodule
module SRAM1RW256x32 (
	A,
	CE,
	WEB,
	OEB,
	CSB,
	I,
	O
);
	input CE;
	input WEB;
	input OEB;
	input CSB;
	input [7:0] A;
	input [31:0] I;
	output [31:0] O;
	wire RE;
	wire WE;
	SRAM1RW256x32_1bit sram_IO0(
		.CE_i(CE),
		.WEB_i(WEB),
		.A_i(A),
		.OEB_i(OEB),
		.CSB_i(CSB),
